function tr(text){return translations[state.user?.language]?.[text]||text;}
function applyTranslations(){const lang=state.user?.language||'en';document.documentElement.lang=lang;const dict=translations[lang];if(!dict)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){const key=node.nodeValue.trim();if(dict[key])node.nodeValue=node.nodeValue.replace(key,dict[key]);}}
let pollTimer = null;

function esc(value='') { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function initials(name='CareMate') { return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join(''); }
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function humanDate(value, opts={month:'short',day:'numeric'}) { if(!value)return 'â€”'; const text=String(value);const d=new Date(/^\d{4}-\d\d-\d\d$/.test(text)?`${text}T12:00:00`:text); return isNaN(d)?esc(value):d.toLocaleDateString(undefined,opts); }
function humanTime(value) { if(!value)return ''; const [h,m]=String(value).split(':').map(Number); if(Number.isNaN(h))return value; const d=new Date(); d.setHours(h,m||0,0,0); return d.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}); }
function toast(message, error=false) { const el=document.createElement('div'); el.className=`toast${error?' error':''}`; el.textContent=message; document.querySelector('#toast-region').append(el); setTimeout(()=>el.remove(),3800); }

async function api(path, options={}) {
  const headers = new Headers(options.headers || {});
  if(state.token) headers.set('Authorization', `Bearer ${state.token}`);
  if(options.body && !(options.body instanceof FormData) && !headers.has('Content-Type')) headers.set('Content-Type','application/json');
  let response;
  try { response=await fetch(path,{...options,headers}); }
  catch { throw new Error('Could not reach CareMate. Check that the backend is running.'); }
  if(response.status===401 && !path.startsWith('/api/auth/')) {
    signOut(false); throw new Error('Your session expired. Please sign in again.');
  }
  if(response.status===204) return null;
  const contentType=response.headers.get('content-type')||'';
  const data=contentType.includes('application/json')?await response.json():await response.text();
  if(!response.ok) throw new Error(data?.detail || data?.message || `Request failed (${response.status})`);
  return data;
}
const json=(method,body)=>({method,body:JSON.stringify(body)});

